## Common Components

### Buttons
Ant Design provides various button types and states:

```jsx
import { Button, Space } from 'antd';

function ButtonExample() {
  return (
    <Space wrap>
      <Button type="primary">Primary</Button>
      <Button>Default</Button>
      <Button type="dashed">Dashed</Button>
      <Button type="text">Text</Button>
      <Button type="link">Link</Button>
      <Button type="primary" danger>Danger</Button>
      <Button type="primary" loading>Loading</Button>
    </Space>
  );
}
```

### Input Components
```jsx
import { Input, Select, Radio, Checkbox } from 'antd';

const { Option } = Select;

function InputExample() {
  return (
    <Space direction="vertical" style={{ width: '100%' }}>
      <Input placeholder="Basic input" />
      <Input.Password placeholder="Password input" />
      <Input.Search placeholder="Search input" />

      <Select defaultValue="option1" style={{ width: '100%' }}>
        <Option value="option1">Option 1</Option>
        <Option value="option2">Option 2</Option>
        <Option value="option3">Option 3</Option>
      </Select>

      <Radio.Group defaultValue="a">
        <Radio value="a">Option A</Radio>
        <Radio value="b">Option B</Radio>
        <Radio value="c">Option C</Radio>
      </Radio.Group>

      <Checkbox>Remember me</Checkbox>
    </Space>
  );
}
```

### Navigation Components
```jsx
import { Menu, Breadcrumb, Tabs } from 'antd';

const { TabPane } = Tabs;

function NavigationExample() {
  return (
    <div>
      <Menu mode="horizontal" defaultSelectedKeys={['mail']}>
        <Menu.Item key="mail">Navigation One</Menu.Item>
        <Menu.Item key="app">Navigation Two</Menu.Item>
        <Menu.SubMenu title="Navigation Three - Submenu">
          <Menu.Item key="setting:1">Option 1</Menu.Item>
          <Menu.Item key="setting:2">Option 2</Menu.Item>
        </Menu.SubMenu>
      </Menu>

      <Breadcrumb style={{ margin: '16px 0' }}>
        <Breadcrumb.Item>Home</Breadcrumb.Item>
        <Breadcrumb.Item>Application</Breadcrumb.Item>
        <Breadcrumb.Item>Dashboard</Breadcrumb.Item>
      </Breadcrumb>

      <Tabs defaultActiveKey="1">
        <TabPane tab="Tab 1" key="1">Content of Tab 1</TabPane>
        <TabPane tab="Tab 2" key="2">Content of Tab 2</TabPane>
        <TabPane tab="Tab 3" key="3">Content of Tab 3</TabPane>
      </Tabs>
    </div>
  );
}
```

### Data Display Components
```jsx
import { Table, List, Card, Tag } from 'antd';

const dataSource = [
  {
    key: '1',
    name: 'John Brown',
    age: 32,
    address: 'New York No. 1 Lake Park',
    tags: ['developer', 'react'],
  },
  {
    key: '2',
    name: 'Jim Green',
    age: 42,
    address: 'London No. 1 Lake Park',
    tags: ['designer', 'ui'],
  },
];

const columns = [
  {
    title: 'Name',
    dataIndex: 'name',
    key: 'name',
  },
  {
    title: 'Age',
    dataIndex: 'age',
    key: 'age',
  },
  {
    title: 'Address',
    dataIndex: 'address',
    key: 'address',
  },
  {
    title: 'Tags',
    key: 'tags',
    dataIndex: 'tags',
    render: tags => (
      <>
        {tags.map(tag => (
          <Tag color="blue" key={tag}>
            {tag}
          </Tag>
        ))}
      </>
    ),
  },
];

function DataDisplayExample() {
  return (
    <div>
      <Card title="User Table" style={{ marginBottom: 16 }}>
        <Table dataSource={dataSource} columns={columns} />
      </Card>

      <Card title="User List">
        <List
          dataSource={dataSource}
          renderItem={item => (
            <List.Item>
              <List.Item.Meta
                title={item.name}
                description={item.address}
              />
              <div>Age: {item.age}</div>
            </List.Item>
          )}
        />
      </Card>
    </div>
  );
}
```

## Layout System

Ant Design provides a powerful layout system based on CSS Flexbox:

### Basic Layout
```jsx
import { Layout, Menu } from 'antd';
import { UserOutlined, VideoCameraOutlined, UploadOutlined } from '@ant-design/icons';

const { Header, Content, Footer, Sider } = Layout;

function LayoutExample() {
  return (
    <Layout style={{ minHeight: '100vh' }}>
      <Sider collapsible>
        <div className="logo" />
        <Menu theme="dark" defaultSelectedKeys={['1']} mode="inline">
          <Menu.Item key="1" icon={<UserOutlined />}>
            nav 1
          </Menu.Item>
          <Menu.Item key="2" icon={<VideoCameraOutlined />}>
            nav 2
          </Menu.Item>
          <Menu.Item key="3" icon={<UploadOutlined />}>
            nav 3
          </Menu.Item>
        </Menu>
      </Sider>
      <Layout>
        <Header style={{ background: '#fff', padding: 0 }} />
        <Content style={{ margin: '0 16px' }}>
          <div style={{ padding: 24, background: '#fff', minHeight: 360 }}>
            Content
          </div>
        </Content>
        <Footer style={{ textAlign: 'center' }}>
          Ant Design ©2023 Created by You
        </Footer>
      </Layout>
    </Layout>
  );
}
```

### Grid System
```jsx
import { Row, Col, Card } from 'antd';

function GridExample() {
  return (
    <div>
      <Row gutter={16}>
        <Col span={8}>
          <Card title="Card title" bordered={false}>
            Card content
          </Card>
        </Col>
        <Col span={8}>
          <Card title="Card title" bordered={false}>
            Card content
          </Card>
        </Col>
        <Col span={8}>
          <Card title="Card title" bordered={false}>
            Card content
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24} sm={12} md={8} lg={6} xl={4}>
          <Card>Responsive Card</Card>
        </Col>
        <Col xs={24} sm={12} md={8} lg={6} xl={4}>
          <Card>Responsive Card</Card>
        </Col>
        <Col xs={24} sm={12} md={8} lg={6} xl={4}>
          <Card>Responsive Card</Card>
        </Col>
      </Row>
    </div>
  );
}
```

## Form Handling

### Basic Form
```jsx
import { Form, Input, Button, Select } from 'antd';

const { Option } = Select;

function BasicForm() {
  const onFinish = (values) => {
    console.log('Success:', values);
  };

  const onFinishFailed = (errorInfo) => {
    console.log('Failed:', errorInfo);
  };

  return (
    <Form
      name="basic"
      labelCol={{ span: 8 }}
      wrapperCol={{ span: 16 }}
      initialValues={{ remember: true }}
      onFinish={onFinish}
      onFinishFailed={onFinishFailed}
      autoComplete="off"
    >
      <Form.Item
        label="Username"
        name="username"
        rules={[{ required: true, message: 'Please input your username!' }]}
      >
        <Input />
      </Form.Item>

      <Form.Item
        label="Password"
        name="password"
        rules={[{ required: true, message: 'Please input your password!' }]}
      >
        <Input.Password />
      </Form.Item>

      <Form.Item
        label="Select"
        name="select"
        rules={[{ required: true, message: 'Please select an option!' }]}
      >
        <Select placeholder="Select an option">
          <Option value="option1">Option 1</Option>
          <Option value="option2">Option 2</Option>
        </Select>
      </Form.Item>

      <Form.Item wrapperCol={{ offset: 8, span: 16 }}>
        <Button type="primary" htmlType="submit">
          Submit
        </Button>
      </Form.Item>
    </Form>
  );
}
```

### Dynamic Form
```jsx
import { Form, Input, Button, Space } from 'antd';
import { MinusCircleOutlined, PlusOutlined } from '@ant-design/icons';

function DynamicForm() {
  const onFinish = (values) => {
    console.log('Received values of form:', values);
  };

  return (
    <Form name="dynamic_form" onFinish={onFinish} autoComplete="off">
      <Form.List name="users">
        {(fields, { add, remove }) => (
          <>
            {fields.map(({ key, name, ...restField }) => (
              <Space key={key} style={{ display: 'flex', marginBottom: 8 }} align="baseline">
                <Form.Item
                  {...restField}
                  name={[name, 'first']}
                  rules={[{ required: true, message: 'Missing first name' }]}
                >
                  <Input placeholder="First Name" />
                </Form.Item>
                <Form.Item
                  {...restField}
                  name={[name, 'last']}
                  rules={[{ required: true, message: 'Missing last name' }]}
                >
                  <Input placeholder="Last Name" />
                </Form.Item>
                <MinusCircleOutlined onClick={() => remove(name)} />
              </Space>
            ))}
            <Form.Item>
              <Button type="dashed" onClick={() => add()} block icon={<PlusOutlined />}>
                Add field
              </Button>
            </Form.Item>
          </>
        )}
      </Form.List>
      <Form.Item>
        <Button type="primary" htmlType="submit">
          Submit
        </Button>
      </Form.Item>
    </Form>
  );
}
```

## Styling and Theming

### Custom Theme (Ant Design v5+)
```jsx
import { ConfigProvider, Button } from 'antd';
import { theme } from 'antd';

const customTheme = {
  token: {
    colorPrimary: '#00b96b',
    borderRadius: 8,
    wireframe: false,
  },
  components: {
    Button: {
      colorPrimary: '#00b96b',
      algorithm: true,
    },
  },
};

function ThemedApp() {
  return (
    <ConfigProvider theme={customTheme}>
      <div>
        <Button type="primary">Custom Themed Button</Button>
        <Button>Default Button</Button>
      </div>
    </ConfigProvider>
  );
}
```

### Dark Mode
```jsx
import { ConfigProvider, Button, Card, Switch } from 'antd';
import { useState } from 'react';

function DarkModeExample() {
  const [isDarkMode, setIsDarkMode] = useState(false);

  const theme = {
    algorithm: isDarkMode ? theme.darkAlgorithm : theme.defaultAlgorithm,
  };

  return (
    <ConfigProvider theme={theme}>
      <Card title={`Theme: ${isDarkMode ? 'Dark' : 'Light'}`}>
        <Switch
          checked={isDarkMode}
          onChange={setIsDarkMode}
          checkedChildren="Dark"
          unCheckedChildren="Light"
        />
        <div style={{ marginTop: 16 }}>
          <Button type="primary">Primary Button</Button>
          <Button style={{ marginLeft: 8 }}>Default Button</Button>
        </div>
      </Card>
    </ConfigProvider>
  );
}
```

### Custom CSS
```css
/* custom.css */
.custom-button {
  background: linear-gradient(45deg, #fe6b8b 30%, #ff8e53 90%);
  border: none;
  color: white;
}

.custom-card {
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  border-radius: 12px;
}
```

```jsx
import './custom.css';
import { Button, Card } from 'antd';

function CustomStyledExample() {
  return (
    <div>
      <Button className="custom-button">Custom Styled Button</Button>
      <Card className="custom-card" title="Custom Card">
        This card has custom styling
      </Card>
    </div>
  );
}
```

## Best Practices

### 1. Import Only What You Need
```jsx
// ✅ Good: Import specific components
import { Button, Input } from 'antd';

// ❌ Avoid: Import everything
import * as antd from 'antd';
```

### 2. Use Semantic Components
```jsx
// ✅ Good: Use semantic components
import { Typography } from 'antd';

const { Title, Paragraph, Text } = Typography;

function GoodExample() {
  return (
    <div>
      <Title level={2}>Page Title</Title>
      <Paragraph>
        This is a paragraph with <Text strong>strong text</Text>.
      </Paragraph>
    </div>
  );
}

// ❌ Avoid: Using plain HTML tags
function BadExample() {
  return (
    <div>
      <h2>Page Title</h2>
      <p>
        This is a paragraph with <strong>strong text</strong>.
      </p>
    </div>
  );
}
```

### 3. Responsive Design
```jsx
import { Row, Col, Card } from 'antd';

function ResponsiveExample() {
  return (
    <Row gutter={[16, 16]}>
      <Col xs={24} sm={12} md={8} lg={6}>
        <Card>Responsive Card 1</Card>
      </Col>
      <Col xs={24} sm={12} md={8} lg={6}>
        <Card>Responsive Card 2</Card>
      </Col>
      <Col xs={24} sm={12} md={8} lg={6}>
        <Card>Responsive Card 3</Card>
      </Col>
    </Row>
  );
}
```

### 4. Form Validation
```jsx
import { Form, Input, Button } from 'antd';

function ValidatedForm() {
  return (
    <Form>
      <Form.Item
        name="email"
        label="Email"
        rules={[
          { required: true, message: 'Please input your email!' },
          { type: 'email', message: 'Please enter a valid email!' }
        ]}
      >
        <Input />
      </Form.Item>

      <Form.Item
        name="password"
        label="Password"
        rules={[
          { required: true, message: 'Please input your password!' },
          { min: 8, message: 'Password must be at least 8 characters!' }
        ]}
      >
        <Input.Password />
      </Form.Item>
    </Form>
  );
}
```

### 5. Loading States
```jsx
import { Button, Spin, Table } from 'antd';
import { useState } from 'react';

function LoadingExample() {
  const [loading, setLoading] = useState(false);

  const handleClick = () => {
    setLoading(true);
    setTimeout(() => setLoading(false), 2000);
  };

  return (
    <div>
      <Button 
        type="primary" 
        loading={loading}
        onClick={handleClick}
      >
        {loading ? 'Loading...' : 'Click me'}
      </Button>

      {loading && (
        <div style={{ marginTop: 16 }}>
          <Spin size="large" />
        </div>
      )}
    </div>
  );
}
```

