TITLE: Create a User Session with Cookies in Next.js
DESCRIPTION: This function, `createSession`, demonstrates how to securely store a user session in a cookie using the Next.js `cookies` API. It takes a `userId`, encrypts it along with an expiration date, and then sets the resulting session string in an `HttpOnly`, `secure` cookie. The `server-only` import ensures this logic runs exclusively on the server.

SOURCE: https://github.com/vercel/next.js/blob/canary/docs/01-app/02-guides/authentication.mdx#_snippet_14

LANGUAGE: typescript
CODE:
```
import 'server-only'
import { cookies } from 'next/headers'

export async function createSession(userId: string) {
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
  const session = await encrypt({ userId, expiresAt })
  const cookieStore = await cookies()

  cookieStore.set('session', session, {
    httpOnly: true,
    secure: true,
    expires: expiresAt,
    sameSite: 'lax',
    path: '/',
  })
}
```

