import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

/**
 * JWT verification function
 * In a real application, you would use a library like 'jose' or 'jsonwebtoken'
 * This is a simplified example for demonstration
 */
function verifyJWT(token: string): boolean {
  try {
    // In production, you would verify the JWT signature and expiration
    // For example: 
    // import { jwtVerify } from 'jose'
    // const { payload } = await jwtVerify(token, secretKey)
    // return payload.exp > Date.now() / 1000

    // For this example, we'll do a basic check
    if (!token) return false

    // Simple validation - in production, use proper JWT verification
    const parts = token.split('.')
    if (parts.length !== 3) return false

    // Decode payload (without verification for this example)
    const payload = JSON.parse(atob(parts[1]))

    // Check if token is expired
    if (payload.exp && payload.exp < Date.now() / 1000) {
      return false
    }

    return true
  } catch (error) {
    console.error('JWT verification failed:', error)
    return false
  }
}

/**
 * Middleware function to check for valid JWT in cookies
 * and redirect unauthenticated users to /login
 */
export function middleware(request: NextRequest) {
  // Get the JWT token from cookies
  const token = request.cookies.get('auth-token')?.value

  // Paths that don't require authentication
  const publicPaths = ['/login', '/register', '/api/auth', '/_next', '/favicon.ico']

  // Check if the current path is public
  const isPublicPath = publicPaths.some(path => 
    request.nextUrl.pathname.startsWith(path)
  )

  // If it's a public path, allow access
  if (isPublicPath) {
    return NextResponse.next()
  }

  // If no token or invalid token, redirect to login
  if (!token || !verifyJWT(token)) {
    // Preserve the original URL for redirect after login
    const loginUrl = new URL('/login', request.url)
    loginUrl.searchParams.set('redirect', request.nextUrl.pathname)

    return NextResponse.redirect(loginUrl)
  }

  // Token is valid, allow access to the requested resource
  return NextResponse.next()
}

