"use client"

import React, { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"

export function CreatePostForm() {
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Check if both fields are filled to enable the button
  const isFormValid = title.trim() !== "" && content.trim() !== ""

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!isFormValid) return

    setIsSubmitting(true)

    try {
      // Simulate API call to create post
      await new Promise(resolve => setTimeout(resolve, 1000))

      console.log("Post created:", { title, content })

      // Reset form after successful submission
      setTitle("")
      setContent("")

      alert("Post published successfully!")
    } catch (error) {
      console.error("Error creating post:", error)
      alert("Failed to publish post. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="w-full max-w-2xl mx-auto p-6">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full"
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="w-full min-h-[200px] resize-none"
          />
        </div>

        <div className="flex justify-end space-x-4">
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              setTitle("")
              setContent("")
            }}
          >
            Cancel
          </Button>

          <Button
            type="submit"
            disabled={!isFormValid || isSubmitting}
            className="min-w-[100px]"
          >
            {isSubmitting ? "Publishing..." : "Publish"}
          </Button>
        </div>

        {/* Visual feedback for form validation */}
        <div className="text-sm text-muted-foreground">
          {!isFormValid && (
            <p>
              {title.trim() === "" && content.trim() === "" 
                ? "Please fill in both title and content to publish."
                : title.trim() === ""
                ? "Please add a title to publish."
                : "Please add content to publish."
              }
            </p>
          )}
          {isFormValid && !isSubmitting && (
            <p className="text-green-600">Ready to publish!</p>
          )}
        </div>
      </form>
    </div>
  )
}

// Alternative version with more advanced validation and character count
export function CreatePostFormAdvanced() {
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  const MAX_TITLE_LENGTH = 100
  const MAX_CONTENT_LENGTH = 5000

  const isFormValid = 
    title.trim().length > 0 && 
    title.trim().length <= MAX_TITLE_LENGTH &&
    content.trim().length > 0 && 
    content.trim().length <= MAX_CONTENT_LENGTH

  const titleError = title.length > MAX_TITLE_LENGTH 
    ? `Title must be ${MAX_TITLE_LENGTH} characters or less` 
    : ""

  const contentError = content.length > MAX_CONTENT_LENGTH 
    ? `Content must be ${MAX_CONTENT_LENGTH} characters or less` 
    : ""

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!isFormValid) return

    setIsSubmitting(true)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))

      console.log("Post created:", { title, content })

      // Reset form
      setTitle("")
      setContent("")

      alert("Post published successfully!")
    } catch (error) {
      console.error("Error creating post:", error)
      alert("Failed to publish post. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="w-full max-w-2xl mx-auto p-6">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <Label htmlFor="title">Title</Label>
            <span className={`text-sm ${
              title.length > MAX_TITLE_LENGTH ? "text-red-500" : "text-muted-foreground"
            }`}>
              {title.length}/{MAX_TITLE_LENGTH}
            </span>
          </div>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className={`w-full ${titleError ? "border-red-500" : ""}`}
          />
          {titleError && (
            <p className="text-sm text-red-500">{titleError}</p>
          )}
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <Label htmlFor="content">Content</Label>
            <span className={`text-sm ${
              content.length > MAX_CONTENT_LENGTH ? "text-red-500" : "text-muted-foreground"
            }`}>
              {content.length}/{MAX_CONTENT_LENGTH}
            </span>
          </div>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className={`w-full min-h-[200px] resize-none ${contentError ? "border-red-500" : ""}`}
          />
          {contentError && (
            <p className="text-sm text-red-500">{contentError}</p>
          )}
        </div>

        <div className="flex justify-end space-x-4">
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              setTitle("")
              setContent("")
            }}
          >
            Cancel
          </Button>

          <Button
            type="submit"
            disabled={!isFormValid || isSubmitting}
            className="min-w-[100px]"
          >
            {isSubmitting ? "Publishing..." : "Publish"}
          </Button>
        </div>

        {/* Form status indicator */}
        <div className="text-sm">
          {!isFormValid && (
            <div className="text-muted-foreground">
              {title.trim() === "" && <p>• Title is required</p>}
              {content.trim() === "" && <p>• Content is required</p>}
              {titleError && <p className="text-red-500">• {titleError}</p>}
              {contentError && <p className="text-red-500">• {contentError}</p>}
            </div>
          )}
          {isFormValid && !isSubmitting && (
            <p className="text-green-600">✓ Ready to publish!</p>
          )}
        </div>
      </form>
    </div>
  )
}

